    },
    {
      "factor": "Lack of Transparency in Decision-Making",
      "polarity": -1,
      "reason_headline": "Inadequate Justification for Trade Decisions",
      "reason_detailed": "The agent's justifications for its trade decisions are often vague and lacking in detail, making it difficult to determine whether the decisions are based on legitimate market analysis or other factors. The agent's reliance on recommendations from StockAnalyze, without providing further context or analysis, is also concerning."
    },
    {
      "factor": "Inconsistent Risk Assessment",
